import type { SQLiteDBConnection } from '@capacitor-community/sqlite'
import journal from './migrations/meta/_journal.json'

// Migration SQL generated by `npm run db:generate`, bundled into the app as strings
const files = import.meta.glob<string>('./migrations/*.sql', { query: '?raw', import: 'default', eager: true })

// Applies any migrations this device hasn't run yet, in journal order.
// Drizzle's own migrator reads files from disk, which a phone app can't do.
export async function runMigrations(conn: SQLiteDBConnection) {
  await conn.execute(`
    CREATE TABLE IF NOT EXISTS __migrations (
      tag TEXT PRIMARY KEY,
      applied_at INTEGER NOT NULL
    );
  `)

  const applied = new Set(
    ((await conn.query('SELECT tag FROM __migrations')).values ?? []).map(row => row.tag),
  )

  for (const { tag } of journal.entries) {
    if (applied.has(tag)) continue

    const sql = files[`./migrations/${tag}.sql`]
    if (sql === undefined) throw new Error(`Migration file missing: ${tag}.sql`)

    // Record the migration in the same transaction, so a failed one is retried next launch
    await conn.execute(
      `${sql.replaceAll('--> statement-breakpoint', '')}
      INSERT INTO __migrations (tag, applied_at) VALUES ('${tag}', ${Date.now()});`,
      true,
    )
  }
}